public enum ThreadAction: Equatable, Hashable {
    
    /**
     * Archive.
     */
    case done
    /**
     * Back into the inbox.
     */
    case moveToInbox
    case trash
    case untrash
    case star
    case unstar
    case markRead
    case markUnread
    case spam
    case notSpam





}

